// A regex is an object, not a string.
const smokePattern = /@smoke/;

console.log(typeof smokePattern);                       // "object"
console.log(smokePattern.test("checkout @smoke"));      // true
console.log(smokePattern.test("checkout @regression")); // false
console.log(smokePattern.test("@smoketest run"));       // true  <- matches inside a word

const eitherTag = /@smoke|@critical/;

for (const title of ["pay bills @smoke", "transfer @critical", "report @regression"]) {
  console.log(`${eitherTag.test(title) ? "RUN " : "skip"}  ${title}`);
}

const baseConfig = { timeout: 30_000, use: { baseURL: "https://example.com", headless: false } };

const brokenCopy = { ...baseConfig, use: { headless: true } };
const fixedCopy  = { ...baseConfig, use: { ...baseConfig.use, headless: true } };

console.log("broken.use:", brokenCopy.use);  // baseURL is gone
console.log("fixed.use: ", fixedCopy.use);   // both kept

import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template literal.

await writeProjectFile("week5/generated/day1-tagged.spec.ts", `// Week 5, Day 1 — one spec, two lanes.
//
// The tags in the test titles are just text. What makes them useful is that a
// config or a --grep can select on them, so the same file serves a 30-second
// smoke run and a full regression run.
//
// Filename is NOT *.spec.ts by root-config standards? It is — but the root
// config's testMatch covers week*/**/*.spec.ts, so it runs there too. That is
// deliberate: these tests are honest tests, not demos.
//
//   npx playwright test -c week5/generated/day1-smoke.config.ts        (2 tests)
//   npx playwright test -c week5/generated/day1-regression.config.ts   (4 tests)
import { test, expect } from "@playwright/test";
import { loginAs } from "../../_shared/test-helpers";

test("@smoke sign-in reaches the dashboard", async ({ page }) => {
  await loginAs(page);
  await expect(page.getByText("Leela")).toBeVisible();
});

test("@smoke the dashboard shows an account balance", async ({ page }) => {
  await loginAs(page);
  await expect(page.getByText("Account Balance", { exact: true })).toBeVisible();
});

test("@regression every dashboard tile is present", async ({ page }) => {
  await loginAs(page);
  // 12 tiles, verified — two of them share the label "Statements".
  await expect(page.locator("p.card-text")).toHaveCount(12);
});

test("@regression signing out returns to the login form", async ({ page }) => {
  await loginAs(page);
  await page.getByRole("button", { name: "LogOut" }).click();
  await expect(page.getByPlaceholder("Enter Email")).toBeVisible();
});
`);

// All four, under the repo's normal config.
await runSpec("week5/generated/day1-tagged.spec.ts");

import { runSpec } from "../_shared/deno-helpers.ts";

// Expected: 2 passed.
await runSpec("week5/generated/day1-tagged.spec.ts", { grep: "@smoke" });

import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template literal.

await writeProjectFile("week5/generated/day1-smoke.config.ts", `// Week 5, Day 1 — one config per purpose: the fast smoke lane.
//
// The point of a second config is that your team's default stays untouched. This
// one runs only tests tagged @smoke, on one browser, with no retries — the shape
// you want on every push.
//
//   npx playwright test -c week5/generated/day1-smoke.config.ts
import { defineConfig, devices } from "@playwright/test";

export default defineConfig({
  testDir: ".",
  testMatch: ["day1-tagged.spec.ts"],
  grep: /@smoke/,          // the config selects the tag; no flag needed
  retries: 0,
  workers: 3,
  reporter: [["list"]],
  use: { ...devices["Desktop Chrome"], baseURL: "https://test-automation-banking.vercel.app" },
});
`);

// Expected: 2 passed. The config picked the tag; we passed no --grep.
await runSpec("week5/generated/day1-tagged.spec.ts", { extraArgs: ["-c", "week5/generated/day1-smoke.config.ts"] });

import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template literal.

await writeProjectFile("week5/generated/day1-regression.config.ts", `// Week 5, Day 1 — the same tests, the slow thorough lane.
//
// Same testMatch, different everything else: no grep (so every tag runs), retries
// on, traces kept. Nothing about the tests changed — only the config.
//
//   npx playwright test -c week5/generated/day1-regression.config.ts
import { defineConfig, devices } from "@playwright/test";

export default defineConfig({
  testDir: ".",
  testMatch: ["day1-tagged.spec.ts"],
  // No grep: everything runs.
  retries: 1,
  workers: 2,
  reporter: [["list"]],
  use: {
    ...devices["Desktop Chrome"],
    baseURL: "https://test-automation-banking.vercel.app",
    trace: "retain-on-failure",
  },
});
`);

// Expected: 4 passed. Same spec file, no grep, retries on.
await runSpec("week5/generated/day1-tagged.spec.ts", { extraArgs: ["-c", "week5/generated/day1-regression.config.ts"] });

import { runSpec } from "../_shared/deno-helpers.ts";

// The config says /@smoke/. The command line says @regression.
// Predict the count before you run it.
await runSpec("week5/generated/day1-tagged.spec.ts", {
  extraArgs: ["-c", "week5/generated/day1-smoke.config.ts", "--grep", "@regression"],
});

import { runSpec } from "../_shared/deno-helpers.ts";

// Now a plain number instead of a filter. The config says workers: 3.
// Expected: "Running 2 tests using 1 worker" - here the flag really does win.
await runSpec("week5/generated/day1-tagged.spec.ts", {
  extraArgs: ["-c", "week5/generated/day1-smoke.config.ts", "--workers=1"],
});

## One base, several thin overrides

Copying a whole config per environment means five files that drift apart. Import the base:

```ts
// config/smoke.config.ts
import { defineConfig } from "@playwright/test";
import base from "../playwright.config";

export default defineConfig({
  ...base,                    // everything the base decided
  grep: /@smoke/,             // the three things this run changes
  retries: 0,
  workers: 3,
});
```

`...base` is the spread from [day1_1](/learn/w5/d1/p1), concept 3 - and its shallowness is exactly
the bug you saw there. `use: { headless: true }` under a `...base` **deletes `baseURL`**. Spread
the inner object too:

```ts
use: { ...base.use, headless: true },
```

// The three-config layout, resolved. No browser needed - this is just objects.
const sharedBase = {
  timeout: 30_000,
  use: { baseURL: "https://test-automation-banking.vercel.app", headless: true },
};

const smokeLane = { ...sharedBase, grep: /@smoke/, retries: 0, workers: 3 };
const ciLane = {
  ...sharedBase,
  use: { ...sharedBase.use, headless: true },   // inner spread: keeps baseURL
  retries: 2,
  workers: 1,
};

for (const [name, cfg] of Object.entries({ smokeLane, ciLane })) {
  console.log(name.padEnd(10), "baseURL:", cfg.use.baseURL ?? "*** LOST ***",
              "| retries:", cfg.retries, "| workers:", cfg.workers);
}

## Naming the runs in package.json

```json
{
  "scripts": {
    "test:smoke":      "playwright test -c config/smoke.config.ts",
    "test:regression": "playwright test -c config/regression.config.ts",
    "test:one":        "playwright test -c config/smoke.config.ts --workers=1 --headed"
  }
}
```

`npm run test:smoke` is now the interface. The flags live in one place, and CI runs the same
command a developer runs.
